def main():
    out = Path(__file__).resolve().parent.parent / "datasets" / "sample_news.csv"
    out.parent.mkdir(exist_ok=True)
    rows = []
    # interleave categories so spread-out dates mix topics across days
    for i in range(max(len(v) for v in ARTICLES.values())):
        for cat, items in ARTICLES.items():
            if i < len(items):
                title, text = items[i]
                rows.append({"title": title, "content": text, "category": cat, "source": "Sample (fictional)"})
    with out.open("w", newline="") as f:
        w = csv.DictWriter(f, fieldnames=["title", "content", "category", "source"])
        w.writeheader()
        w.writerows(rows)
    print(f"Wrote {len(rows)} articles to {out}")


if __name__ == "__main__":
    main()
